t.script:
(function () {
    var current = '';
    var sheets = document.querySelectorAll('.fl-sheet');
    var picks = document.querySelectorAll('.fl-pick');
    var wrap = document.getElementById('flShare');
    var title = wrap ? (wrap.getAttribute('data-title') || 'Property Flier') : 'Property Flier';
    var wa = document.getElementById('flShareWa');
    var mail = document.getElementById('flShareMail');

    function pageUrl() { return window.location.href; }

    /* link opened by the QR code (the property information page) */
    function infoUrl() {
        var img = document.querySelector('.fl-qr-img');
        var u = img ? img.getAttribute('data-qr') : '';
        return u ? u : pageUrl();
    }

    /* ---------- QR: if the server could not draw it, draw it here ---------- */
    function fixQr(img) {
        if (img.naturalWidth > 0) { return; }
        if (img.getAttribute('data-qr-fixed')) { return; }
        var text = img.getAttribute('data-qr');
        if (!text) { return; }
        if (typeof QRCode === 'undefined') { return; }
        img.setAttribute('data-qr-fixed', '1');
        var tmp = document.createElement('div');
        try {
            new QRCode(tmp, { text: text, width: 240, height: 240, correctLevel: QRCode.CorrectLevel.M });
        } catch (e) { return; }
        var c = tmp.querySelector('canvas');
        if (c) { img.src = c.toDataURL('image/png'); }
    }
    document.querySelectorAll('.fl-qr-img').forEach(function (img) {
        img.addEventListener('error', function () { fixQr(img); });
    });
    window.addEventListener('load', function () {
        document.querySelectorAll('.fl-qr-img').forEach(fixQr);
    });

    function refreshShareLinks() {
        var url = pageUrl();
        if (wa) { wa.href = 'https://wa.me/?text=' + encodeURIComponent(title + ' ' + url); }
        if (mail) {
            mail.href = 'https://mail.google.com/mail/?view=cm&fs=1&su=' + encodeURIComponent(title) +
                '&body=' + encodeURIComponent(url);
        }
    }

    /* ---------- design picker ---------- */
    function selectDesign(n) {
        current = String(n);
        sheets.forEach(function (s) {
            s.classList.toggle('active', s.id === 'flierSheet' + current);
        });
        picks.forEach(function (p) {
            p.classList.toggle('active', p.getAttribute('data-design') === current);
        });
        try {
            var u = new URL(window.location.href);
            u.searchParams.set('design', current);
            window.history.replaceState(null, '', u.toString());
        } catch (e) {}
        refreshShareLinks();
    }
    picks.forEach(function (p) {
        p.addEventListener('click', function () { selectDesign(p.getAttribute('data-design')); });
    });
    selectDesign(current);

    /* ---------- image rendering (PNG) ---------- */
    function renderBlob(done) {
        var node = document.getElementById('flierSheet' + current);
        function viaCanvas() {
            if (typeof html2canvas === 'undefined') { done(null); return; }
            html2canvas(node, { scale: 2, useCORS: true, backgroundColor: null })
                .then(function (c) { c.toBlob(function (b) { done(b); }, 'image/png'); })
                .catch(function () { done(null); });
        }
        if (window.htmlToImage) {
            window.htmlToImage.toBlob(node, { pixelRatio: 2, cacheBust: true, width: node.offsetWidth, height: node.offsetHeight, style: { margin: '0', maxWidth: 'none', transform: 'none', boxShadow: 'none', borderRadius: '0' } })
                .then(function (b) { if (b) { done(b); } else { viaCanvas(); } })
                .catch(viaCanvas);
        } else {
            viaCanvas();
        }
    }
    function saveBlob(blob) {
        if (!blob) { window.print(); return; }
        var a = document.createElement('a');
        a.download = 'property-flier-' + current + '.png';
        a.href = URL.createObjectURL(blob);
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
    }


    /* ---------- PDF with clickable QR code ---------- */
    function blobToDataUrl(blob, cb) {
        var fr = new FileReader();
        fr.onload = function () { cb(fr.result); };
        fr.readAsDataURL(blob);
    }
    function buildPdf(done) {
        var node = document.getElementById('flierSheet' + current);
        if (!window.jspdf) { done(null); return; }
        renderBlob(function (blob) {
            if (!blob) { done(null); return; }
            blobToDataUrl(blob, function (dataUrl) {
                try {
                    var w = node.offsetWidth;
                    var h = node.offsetHeight;
                    var doc = new window.jspdf.jsPDF({
                        orientation: w > h ? 'l' : 'p',
                        unit: 'px', format: [w, h], hotfixes: ['px_scaling']
                    });
                    doc.addImage(dataUrl, 'PNG', 0, 0, w, h);
                    var base = node.getBoundingClientRect();
                    /* QR code -> property information page */
                    node.querySelectorAll('.fl-qr-img').forEach(function (q) {
                        var r = q.getBoundingClientRect();
                        doc.link(r.left - base.left, r.top - base.top, r.width, r.height,
                                 { url: q.getAttribute('data-qr') || infoUrl() });
                    });
                    /* phone number -> tap to call */
                    var ph = node.querySelector('.pf-phone, .cta b, .foot b, .bar b');
                    if (ph) {
                        var digits = (ph.textContent || '').replace(/[^0-9+]/g, '');
                        if (digits) {
                            var pr = ph.getBoundingClientRect();
                            doc.link(pr.left - base.left, pr.top - base.top, pr.width, pr.height,
                                     { url: 'tel:' + digits });
                        }
                    }
                    done(doc.output('blob'));
                } catch (e) { done(null); }
            });
        });
    }
    function savePdf(blob) {
        if (!blob) { window.print(); return; }
        var a = document.createElement('a');
        a.download = 'property-flier-' + current + '.pdf';
        a.href = URL.createObjectURL(blob);
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
    }
    var pdfBtn = document.getElementById('flierDownloadPdf');
    if (pdfBtn) {
        pdfBtn.addEventListener('click', function () { buildPdf(savePdf); });
    }

    var png = document.getElementById('flierDownloadPng');
    if (png) {
        png.addEventListener('click', function () { renderBlob(saveBlob); });
    }

    /* ---------- share menu ---------- */
    if (!wrap) { return; }
    var btn = document.getElementById('flShareBtn');
    var menu = document.getElementById('flShareMenu');

    function closeMenu() { menu.classList.remove('open'); btn.setAttribute('aria-expanded', 'false'); }
    btn.addEventListener('click', function (e) {
        e.stopPropagation();
        var open = menu.classList.toggle('open');
        btn.setAttribute('aria-expanded', open ? 'true' : 'false');
    });
    document.addEventListener('click', function (e) { if (!wrap.contains(e.target)) { closeMenu(); } });
    document.addEventListener('keydown', function (e) { if (e.key === 'Escape') { closeMenu(); } });
    menu.querySelectorAll('a').forEach(function (a) { a.addEventListener('click', closeMenu); });

    var copyBtn = document.getElementById('flShareCopy');
    copyBtn.addEventListener('click', function () {
        var label = copyBtn.querySelector('span');
        var url = pageUrl();
        function done(ok) {
            label.textContent = ok ? 'Link copied!' : 'Copy failed';
            setTimeout(function () { label.textContent = 'Copy link'; closeMenu(); }, 1200);
        }
        if (navigator.clipboard && window.isSecureContext) {
            navigator.clipboard.writeText(url).then(function () { done(true); }, function () { done(false); });
        } else {
            var ta = document.createElement('textarea');
            ta.value = url; ta.style.position = 'fixed'; ta.style.opacity = '0';
            document.body.appendChild(ta); ta.select();
            var ok = false;
            try { ok = document.execCommand('copy'); } catch (err) {}
            document.body.removeChild(ta);
            done(ok);
        }
    });

    var pdfShare = document.getElementById('flSharePdf');
    if (pdfShare) {
        pdfShare.addEventListener('click', function () {
            closeMenu();
            buildPdf(function (blob) {
                if (!blob) { window.print(); return; }
                var file = new File([blob], 'property-flier-' + current + '.pdf', { type: 'application/pdf' });
                if (navigator.canShare) {
                    if (navigator.canShare({ files: [file] })) {
                        navigator.share({ files: [file], title: title, text: title + ' ' + infoUrl() }).catch(function () {});
                        return;
                    }
                }
                savePdf(blob);
            });
        });
    }

    var imgBtn = document.getElementById('flShareImg');
    if (imgBtn) {
        imgBtn.addEventListener('click', function () {
            closeMenu();
            renderBlob(function (blob) {
                if (!blob) { window.print(); return; }
                var file = new File([blob], 'property-flier-' + current + '.png', { type: 'image/png' });
                if (navigator.canShare) {
                    if (navigator.canShare({ files: [file] })) {
                        navigator.share({ files: [file], title: title, text: title + ' - details: ' + infoUrl() }).catch(function () {});
                        return;
                    }
                }
                saveBlob(blob);
            });
        });
    }
})();

(function () {
    /* ---------- chat assistant ---------- */
    var chatId = ;
    var msgs = document.getElementById('piChatMessages');
    var input = document.getElementById('piChatInput');
    var send = document.getElementById('piChatSend');
    function addBubble(role, text, loading) {
        var b = document.createElement('div');
        b.className = 'pi-bubble pi-' + role + (loading ? ' pi-loading' : '');
        b.textContent = text;
        msgs.appendChild(b);
        msgs.scrollTop = msgs.scrollHeight;
        return b;
    }
    function ask() {
        var q = (input.value || '').trim();
        if (!q) { return; }
        addBubble('user', q, false);
        input.value = '';
        send.disabled = true;
        var wait = addBubble('bot', 'Thinking...', true);
        var fd = new FormData();
        fd.append('question', q);
        fetch('/api/property/' + chatId + '/ask', { method: 'POST', body: fd })
            .then(function (r) { return r.json(); })
            .then(function (d) {
                wait.classList.remove('pi-loading');
                wait.textContent = d.success ? d.answer : (d.error || 'Sorry, something went wrong.');
                if (!d.success) { wait.classList.add('pi-error'); }
            })
            .catch(function () {
                wait.classList.remove('pi-loading');
                wait.classList.add('pi-error');
                wait.textContent = 'Sorry, something went wrong. Please try again.';
            })
            .then(function () { send.disabled = false; msgs.scrollTop = msgs.scrollHeight; });
    }
    if (send) {
        send.addEventListener('click', ask);
        input.addEventListener('keydown', function (e) {
            if (e.key === 'Enter') { e.preventDefault(); ask(); }
        });
    }

    /* ---------- registration form ---------- */
    var form = document.getElementById('piRegForm');
    if (form) {
        var box = document.getElementById('piRegMsg');
        var btn = document.getElementById('piRegSubmit');
        function clearErrors() {
            form.querySelectorAll('.pi-err').forEach(function (e) { e.textContent = ''; });
            form.querySelectorAll('.pi-invalid').forEach(function (e) { e.classList.remove('pi-invalid'); });
            box.className = 'pi-reg-msg'; box.textContent = '';
        }
        form.addEventListener('submit', function (ev) {
            ev.preventDefault();
            clearErrors();
            btn.disabled = true; btn.textContent = 'Submitting...';
            fetch(form.getAttribute('data-action'), { method: 'POST', body: new FormData(form) })
                .then(function (r) { return r.json(); })
                .then(function (d) {
                    if (d.success) {
                        form.reset();
                        box.className = 'pi-reg-msg pi-ok';
                        box.textContent = 'Thank you! Your registration (' + d.reference + ') was submitted. We will get back to you soon.';
                    } else {
                        box.className = 'pi-reg-msg pi-bad';
                        box.textContent = d.error || 'Could not submit. Please try again.';
                        Object.keys(d.errors || {}).forEach(function (k) {
                            var f = form.querySelector('[name="' + k + '"]');
                            var m = form.querySelector('[data-err="' + k + '"]');
                            if (f) { f.classList.add('pi-invalid'); }
                            if (m) { m.textContent = d.errors[k]; }
                        });
                    }
                })
                .catch(function () {
                    box.className = 'pi-reg-msg pi-bad';
                    box.textContent = 'Network error. Please try again.';
                })
                .then(function () { btn.disabled = false; btn.textContent = 'Submit Registration'; });
        });
    }
})();
